('NL:software-developer','2026-08-12',null,19.43,38400,15,0,0,0,12,6,0,3,5,41,'career-opportunity-nl-v1','provisional',jsonb_build_object('classification_scope','ISCO-08 2512 Software Developers.','shortage_note','UWV 2026 higher-education guidance says demand for software developers remains substantial, while wider ICT tightness has moderated; 15/20.','visa_basis','No software-developer-specific Dutch immigration fast track exists. Highly Skilled Migrant access requires a recognised sponsor, market-rate pay and the applicable 2026 salary criterion; 3/10.','salary_method','Studiekeuze123 HBO Informatica estimated starting salary EUR 3,200/month, annualised to EUR 38,400; transparent graduate proxy, not an occupation-wide median; 6/10.','entry_basis','HBO Informatica/HBO-ICT and associate-degree software routes provide direct entry, with practical portfolio skills valued; 12/15.','entry_burden_basis','No universal statutory software-developer registration; 5/5.'),'2026-08-12'),
